						if ((java.lang.Long.compareUnsigned(k_2, (q!!.msx)!!.size()) < 0) && (java.lang.Long.compareUnsigned(k_2, (rx!!.msx_ext_mass_in)!!.size()) < 0)) {
							(rx!!.msx_ext_mass_in)!!.a!![k_2.toInt()] += (q!!.msx)!!.a!![k_2.toInt()] / dt
						}
						m++
					}
					if ((ctx!!.options)!!.water_age && (java.lang.Long.compareUnsigned(i, ((ctx!!.water_age_state)!!.node_age_vol_in)!!.size()) < 0)) {
						((ctx!!.water_age_state)!!.node_age_vol_in)!!.a!![i.toInt()] += (q!!.age_vol)!!.a!![i.toInt()] / dt
					}
					if ((ctx!!.options)!!.heat_transport && (java.lang.Long.compareUnsigned(i, ((ctx!!.heat_state)!!.node_temp_vol_in)!!.size()) < 0)) {
						((ctx!!.heat_state)!!.node_temp_vol_in)!!.a!![i.toInt()] += (q!!.temp_vol)!!.a!![i.toInt()] / dt
					}
					i++
				}
				q!!.clear()
				return@__lam1
			}
		apply!!.invoke(ctx!!.surface_outfall_quality, mb!!.qual_routing_ex_in)
		apply!!.invoke(ctx!!.link_gain_quality, mb!!.qual_routing_gw_in)
	}

	open fun addWetWeatherLoads(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		var i: Int = 0
		__L1@ while (i < ctx!!.n_subcatches()) {
			var ui: Long = i.toLong()
			var out_node: Int = ((ctx!!.subcatches)!!.outlet_node)!!.a!![ui.toInt()]
			if ((out_node < 0) || (out_node >= ctx!!.n_nodes())) {
				i++
				continue@__L1
			}
			var ud: Long = out_node.toLong()
			var f: Double = ctx!!.runoff_interp_f
			var f1: Double = 1.0 - f
			var q_new: Double = ((ctx!!.subcatches)!!.runoff)!!.a!![ui.toInt()]
			var q_old: Double = ((ctx!!.subcatches)!!.old_runoff)!!.a!![ui.toInt()]
			var q: Double = (f1 * q_old) + (f * q_new)
			if (q <= 0.0) {
				i++
				continue@__L1
			}
			((ctx!!.nodes)!!.qual_vol_in)!!.a!![ud.toInt()] += q * dt
			if (java.lang.Long.compareUnsigned(ud, this.qual_vol_lat_!!.size()) < 0) {
				this.qual_vol_lat_!!.a!![ud.toInt()] += q * dt
			}
			var have_sc: Boolean = (ctx!!.options)!!.water_age && (java.lang.Long.compareUnsigned(ui, ((ctx!!.water_age_state)!!.subcatch_runoff_age)!!.size()) < 0)
			if (have_sc) {
				var acc: cpp.VecD? = (ctx!!.water_age_state)!!.node_age_vol_in
				if (java.lang.Long.compareUnsigned(ud, acc!!.size()) < 0) {
					acc!!.a!![ud.toInt()] += q * ((ctx!!.water_age_state)!!.subcatch_runoff_age)!!.a!![ui.toInt()]
				}
			} else {
				F_quality__anon_quality_QualityRouting_cpp.addAgeVolume_QualityRouting(ctx, out_node, q, WaterAgeSource.RAINFALL)
			}
			var have_sc_2: Boolean = (ctx!!.options)!!.heat_transport && (java.lang.Long.compareUnsigned(ui, ((ctx!!.heat_state)!!.subcatch_runoff_temp)!!.size()) < 0)
			if (have_sc_2) {
				var acc_2: cpp.VecD? = (ctx!!.heat_state)!!.node_temp_vol_in
				if (java.lang.Long.compareUnsigned(ud, acc_2!!.size()) < 0) {
					acc_2!!.a!![ud.toInt()] += q * ((ctx!!.heat_state)!!.subcatch_runoff_temp)!!.a!![ui.toInt()]
				}
			} else {
				F_quality__anon_quality_QualityRouting_cpp.addTempVolume_QualityRouting(ctx, out_node, q, HeatSource.RAINFALL)
			}
			var p: Int = 0
			__L2@ while (p < np) {
				var sc_idx: Long = (ui * np.toLong()) + p.toLong()
				var nd_idx: Long = (ud * np.toLong()) + p.toLong()
				var c_new: Double = if (java.lang.Long.compareUnsigned(sc_idx, ((ctx!!.subcatches)!!.conc)!!.size()) < 0) ((ctx!!.subcatches)!!.conc)!!.a!![sc_idx.toInt()] else 0.0
				var c_old: Double = if (java.lang.Long.compareUnsigned(sc_idx, ((ctx!!.subcatches)!!.conc_old)!!.size()) < 0) ((ctx!!.subcatches)!!.conc_old)!!.a!![sc_idx.toInt()] else 0.0
				var mass_rate: Double = (f1 * (q_old * c_old)) + (f * (q_new * c_new))
				if ((mass_rate > 0.0) && (java.lang.Long.compareUnsigned(nd_idx, ((ctx!!.nodes)!!.qual_mass_in)!!.size()) < 0)) {
					((ctx!!.nodes)!!.qual_mass_in)!!.a!![nd_idx.toInt()] += mass_rate
				}
				var pi: Long = p.toLong()
				if ((mass_rate > 0.0) && (java.lang.Long.compareUnsigned(pi, ((ctx!!.mass_balance)!!.qual_routing_wet)!!.size()) < 0)) {
					((ctx!!.mass_balance)!!.qual_routing_wet)!!.a!![pi.toInt()] += mass_rate * dt
				}
				p++
			}
			i++
		}
		var f_dr: Double = ctx!!.runoff_interp_f
		var f1_dr: Double = 1.0 - f_dr
		var j: Int = 0
		__L3@ while (j < ctx!!.n_nodes()) {
			var uj: Long = j.toLong()
			var v_new: Double = if (java.lang.Long.compareUnsigned(uj, ((ctx!!.nodes)!!.lid_drain_qual_vol)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_vol)!!.a!![uj.toInt()] else 0.0
			var v_old: Double = if (java.lang.Long.compareUnsigned(uj, ((ctx!!.nodes)!!.lid_drain_qual_vol_old)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_vol_old)!!.a!![uj.toInt()] else 0.0
			var drain_vol_rate: Double = (f1_dr * v_old) + (f_dr * v_new)
			if (drain_vol_rate <= 0.0) {
				j++
				continue@__L3
			}
			((ctx!!.nodes)!!.qual_vol_in)!!.a!![uj.toInt()] += drain_vol_rate * dt
			if (java.lang.Long.compareUnsigned(uj, this.qual_vol_lat_!!.size()) < 0) {
				this.qual_vol_lat_!!.a!![uj.toInt()] += drain_vol_rate * dt
			}
			if (((ctx!!.options)!!.water_age && (java.lang.Long.compareUnsigned(uj, ((ctx!!.water_age_state)!!.node_lid_drain_age_vol_in)!!.size()) < 0)) && (ctx!!.lid_layer_state)!!.active()) {
				var acc_3: cpp.VecD? = (ctx!!.water_age_state)!!.node_age_vol_in
				if (java.lang.Long.compareUnsigned(uj, acc_3!!.size()) < 0) {
					acc_3!!.a!![uj.toInt()] += ((ctx!!.water_age_state)!!.node_lid_drain_age_vol_in)!!.a!![uj.toInt()]
				}
			} else {
				F_quality__anon_quality_QualityRouting_cpp.addAgeVolume_QualityRouting(ctx, j, drain_vol_rate, WaterAgeSource.RAINFALL)
			}
			if (((ctx!!.options)!!.heat_transport && (java.lang.Long.compareUnsigned(uj, ((ctx!!.heat_state)!!.node_lid_drain_temp_vol_in)!!.size()) < 0)) && (ctx!!.lid_layer_state)!!.active()) {
				var tacc: cpp.VecD? = (ctx!!.heat_state)!!.node_temp_vol_in
				if (java.lang.Long.compareUnsigned(uj, tacc!!.size()) < 0) {
					tacc!!.a!![uj.toInt()] += ((ctx!!.heat_state)!!.node_lid_drain_temp_vol_in)!!.a!![uj.toInt()]
				}
			} else {
				F_quality__anon_quality_QualityRouting_cpp.addTempVolume_QualityRouting(ctx, j, drain_vol_rate, HeatSource.RAINFALL)
			}
			var p_2: Int = 0
			__L4@ while (p_2 < np) {
				var nd_idx_2: Long = (uj * np.toLong()) + p_2.toLong()
				var w_new: Double = if (java.lang.Long.compareUnsigned(nd_idx_2, ((ctx!!.nodes)!!.lid_drain_qual_load)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_load)!!.a!![nd_idx_2.toInt()] else 0.0
				var w_old: Double = if (java.lang.Long.compareUnsigned(nd_idx_2, ((ctx!!.nodes)!!.lid_drain_qual_load_old)!!.size()) < 0) ((ctx!!.nodes)!!.lid_drain_qual_load_old)!!.a!![nd_idx_2.toInt()] else 0.0
				var load: Double = (f1_dr * w_old) + (f_dr * w_new)
				if ((load > 0.0) && (java.lang.Long.compareUnsigned(nd_idx_2, ((ctx!!.nodes)!!.qual_mass_in)!!.size()) < 0)) {
					((ctx!!.nodes)!!.qual_mass_in)!!.a!![nd_idx_2.toInt()] += load
				}
				var pi_2: Long = p_2.toLong()
				if ((load > 0.0) && (java.lang.Long.compareUnsigned(pi_2, ((ctx!!.mass_balance)!!.qual_routing_wet)!!.size()) < 0)) {
					((ctx!!.mass_balance)!!.qual_routing_wet)!!.a!![pi_2.toInt()] += load * dt
				}
				p_2++
			}
			j++
		}
	}

	open fun updateLinkQuality(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		var links: LinkData? = ctx!!.links
		var nodes: NodeData? = ctx!!.nodes
		var poll: PollutantData? = ctx!!.pollutants
		var mb: SimulationContext_MassBalance? = ctx!!.mass_balance
		var is_steady: Boolean = (ctx!!.options)!!.routing_model == RoutingModel.STEADY
		var reactions_active: Boolean = F_transport.legacyReactionsActive(ctx)
		var CD: ConduitData? = (ctx!!.link_subtypes)!!.conduits
		var j: Int = 0
		__L1@ while (j < ctx!!.n_links()) {
			var uj: Long = j.toLong()
			var upstream: Int = (if ((links!!.flow)!!.a!![uj.toInt()] >= 0.0) cpp.RefI.Arr((links!!.node1)!!.a, uj.toInt()) else cpp.RefI.Arr((links!!.node2)!!.a, uj.toInt()))!!.get()
			if ((upstream < 0) || (upstream >= ctx!!.n_nodes())) {
				j++
				continue@__L1
			}
			var un: Long = upstream.toLong()
			if (F_quality.linkTakesUpstreamValue(ctx, j)) {
				var p: Int = 0
				__L2@ while (p < np) {
					var li: Long = (uj * np.toLong()) + p.toLong()
					var ni: Long = (un * np.toLong()) + p.toLong()
					if ((java.lang.Long.compareUnsigned(li, (links!!.conc)!!.size()) >= 0) || (java.lang.Long.compareUnsigned(ni, (nodes!!.conc)!!.size()) >= 0)) {
						break@__L2
					}
					(links!!.conc)!!.a!![li.toInt()] = F_lidnode.outletQuality(ctx, upstream, j, p, (nodes!!.conc)!!.a!![ni.toInt()])
					p++
				}
				j++
				continue@__L1
			}
			var cr: Int = (ctx!!.link_subtypes)!!.conduit_row(j)
			var ucr: Long = (if (cr < 0) 0 else cr).toLong()
			var barrels: Double = if (cr >= 0) ((CD!!.barrels)!!.a!![ucr.toInt()]).toDouble() else 1.0
			var q_seep: Double = if (cr >= 0) (CD!!.seep_loss_rate)!!.a!![ucr.toInt()] * barrels else 0.0
			var v_evap: Double = if (cr >= 0) ((CD!!.evap_loss_rate)!!.a!![ucr.toInt()] * barrels) * dt else 0.0
			var v_old: Double = (links!!.old_volume)!!.a!![uj.toInt()]
			var f_evap: Double = 1.0
			if ((v_evap > 0.0) && (v_old > F_quality.ZERO_VOLUME)) {
				f_evap += v_evap / v_old
			}
			var q_in: Double = F_quality.conduitMixingInflow(ctx, j, dt)
			var dry: Boolean = (!is_steady) && F_quality.linkIsDry(ctx, j)
			var p_2: Int = 0
			__L3@ while (p_2 < np) {
				var li_2: Long = (uj * np.toLong()) + p_2.toLong()
				var ni_2: Long = (un * np.toLong()) + p_2.toLong()
				if ((java.lang.Long.compareUnsigned(li_2, (links!!.conc)!!.size()) >= 0) || (java.lang.Long.compareUnsigned(ni_2, (nodes!!.conc)!!.size()) >= 0)) {
					p_2++
					continue@__L3
				}
				var up: Long = p_2.toLong()
				var k: Double = if (java.lang.Long.compareUnsigned(up, (poll!!.k_decay)!!.size()) < 0) (poll!!.k_decay)!!.a!![up.toInt()] else 0.0
				if (reactions_active) {
					k = 0.0
				}
				var c_new: Double = 0.0
				var reacted: Double = 0.0
				var seeped: Double = 0.0
				if (is_steady) {
					var n1: Int = (links!!.node1)!!.a!![uj.toInt()]
					if ((n1 < 0) || (n1 >= ctx!!.n_nodes())) {
						p_2++
						continue@__L3
					}
					var n1i: Long = (n1.toLong() * np.toLong()) + up
					if (java.lang.Long.compareUnsigned(n1i, (nodes!!.conc)!!.size()) >= 0) {
						p_2++
						continue@__L3
					}
					var c1: Double = (nodes!!.conc)!!.a!![n1i.toInt()]
					seeped = (q_seep * c1) * dt
					c1 *= f_evap
					c_new = c1
					if (k > 0.0) {
						c_new = cpp.M.max_d_d(0.0, c1 * cpp.SysMath.Exp_d((-k) * dt))
						reacted = ((c1 - c_new) * (links!!.flow)!!.a!![uj.toInt()]) * dt
					}
				} else {
					var c1_2: Double = (links!!.conc_old)!!.a!![li_2.toInt()]
					seeped = (q_seep * c1_2) * dt
					c1_2 *= f_evap
					var c2: Double = c1_2 * cpp.M.max_d_d(1.0 - (k * dt), 0.0)
					reacted = (c1_2 - c2) * v_old
					if (q_in <= F_quality.LEGACY_ZERO) {
						c_new = c2
					} else {
						var w_in: Double = F_lidnode.outletQuality(ctx, upstream, j, p_2, (nodes!!.conc)!!.a!![ni_2.toInt()]) * q_in
						var v_in: Double = q_in * dt
						var c_in: Double = (w_in * dt) / v_in
						var c_max: Double = cpp.M.max_d_d(c2, c_in)
						c_new = ((c2 * v_old) + (w_in * dt)) / (v_old + v_in)
						c_new = cpp.M.min_d_d(c_new, c_max)
						c_new = cpp.M.max_d_d(c_new, 0.0)
					}
					if (dry) {
						if (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_final_dry)!!.size()) < 0) {
							(mb!!.qual_routing_final_dry)!!.a!![up.toInt()] += c_new * (links!!.volume)!!.a!![uj.toInt()]
						}
						c_new = 0.0
					}
				}
				c_new = cpp.M.max_d_d(c_new, 0.0)
				(links!!.conc)!!.a!![li_2.toInt()] = c_new
				if ((reacted > 0.0) && (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_reacted)!!.size()) < 0)) {
					(mb!!.qual_routing_reacted)!!.a!![up.toInt()] += reacted
				}
				if ((seeped != 0.0) && (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_seep)!!.size()) < 0)) {
					(mb!!.qual_routing_seep)!!.a!![up.toInt()] += seeped
				}
				p_2++
			}
			j++
		}
	}

	open fun applyTreatment(ctx: SimulationContext?, dt: Double, full_inflow: Boolean) {
		var np: Int = this.n_pollutants_
		if (np <= 0) {
			return
		}
		var treat: TreatmentData? = ctx!!.treatment
		if (!(treat!!.hasAny())) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var nn: Int = ctx!!.n_nodes()
		var j: Int = 0
		__L1@ while (j < nn) {
			var uj: Long = j.toLong()
			if (!((treat!!.has_treatment)!!.a!![uj.toInt()])) {
				j++
				continue@__L1
			}
			var vol_in: Double = (nodes!!.qual_vol_in)!!.a!![uj.toInt()]
			var q_raw: Double = if (dt > 0.0) vol_in / dt else 0.0
			var p: Int = 0
			__L2@ while (p < np) {
				var mi: Long = (uj * np.toLong()) + p.toLong()
				var have: Boolean = java.lang.Long.compareUnsigned(mi, (nodes!!.qual_mass_in)!!.size()) < 0
				if (full_inflow) {
					(treat!!.cin)!!.a!![p.toLong().toInt()] = if ((q_raw > 0.0) && have) (nodes!!.qual_mass_in)!!.a!![mi.toInt()] / q_raw else 0.0
				} else {
					(treat!!.cin)!!.a!![p.toLong().toInt()] = if ((vol_in > 0.0) && have) (nodes!!.qual_mass_in)!!.a!![mi.toInt()] / vol_in else 0.0
				}
				p++
			}
			F_quality.applyNodeTreatment(ctx, j, dt, q_raw, (treat!!.cin)!!.data())
			j++
		}
	}

	open fun addRdiiLoads(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		if (!F_quality__anon_quality_QualityRouting_cpp.loadersNeeded_QualityRouting(np, ctx)) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var i: Int = 0
		__L1@ while (i < ctx!!.n_nodes()) {
			var ui: Long = i.toLong()
			var q: Double = (nodes!!.rdii_inflow)!!.a!![ui.toInt()]
			if (q <= 0.0) {
				i++
				continue@__L1
			}
			(nodes!!.qual_vol_in)!!.a!![ui.toInt()] += q * dt
			this.qual_vol_lat_!!.a!![ui.toInt()] += q * dt
			F_quality__anon_quality_QualityRouting_cpp.addAgeVolume_QualityRouting(ctx, i, q, WaterAgeSource.RDII)
			F_quality__anon_quality_QualityRouting_cpp.addTempVolume_QualityRouting(ctx, i, q, HeatSource.RDII)
			var p: Int = 0
			__L2@ while (p < np) {
				var c_rdii: Double = ((ctx!!.pollutants)!!.c_rdii)!!.a!![p.toLong().toInt()]
				if (c_rdii <= 0.0) {
					p++
					continue@__L2
				}
				var nd_idx: Long = (ui * np.toLong()) + p.toLong()
				if (java.lang.Long.compareUnsigned(nd_idx, (nodes!!.qual_mass_in)!!.size()) < 0) {
					(nodes!!.qual_mass_in)!!.a!![nd_idx.toInt()] += q * c_rdii
				}
				p++
			}
			var p_2: Int = 0
			__L3@ while (p_2 < np) {
				var c_rdii_2: Double = ((ctx!!.pollutants)!!.c_rdii)!!.a!![p_2.toLong().toInt()]
				if (c_rdii_2 <= 0.0) {
					p_2++
					continue@__L3
				}
				var pi: Long = p_2.toLong()
				if (java.lang.Long.compareUnsigned(pi, ((ctx!!.mass_balance)!!.qual_routing_ii_in)!!.size()) < 0) {
					((ctx!!.mass_balance)!!.qual_routing_ii_in)!!.a!![pi.toInt()] += (q * c_rdii_2) * dt
				}
				p_2++
			}
			i++
		}
	}

	open fun addDwfLoads(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		if (!F_quality__anon_quality_QualityRouting_cpp.loadersNeeded_QualityRouting(np, ctx)) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var i: Int = 0
		__L1@ while (i < ctx!!.n_nodes()) {
			var ui: Long = i.toLong()
			var q: Double = (nodes!!.dwf_inflow)!!.a!![ui.toInt()]
			if ((q < 0.0) && (java.lang.Long.compareUnsigned(ui, this.qual_vol_lat_neg_!!.size()) < 0)) {
				this.qual_vol_lat_neg_!!.a!![ui.toInt()] += q * dt
			}
			if (q <= 0.0) {
				i++
				continue@__L1
			}
			(nodes!!.qual_vol_in)!!.a!![ui.toInt()] += q * dt
			this.qual_vol_lat_!!.a!![ui.toInt()] += q * dt
			F_quality__anon_quality_QualityRouting_cpp.addAgeVolume_QualityRouting(ctx, i, q, WaterAgeSource.DWF)
			F_quality__anon_quality_QualityRouting_cpp.addTempVolume_QualityRouting(ctx, i, q, HeatSource.DWF)
			var p: Int = 0
			__L2@ while (p < np) {
				var c_dwf: Double = ((ctx!!.pollutants)!!.c_dwf)!!.a!![p.toLong().toInt()]
				var nd_idx: Long = (ui * np.toLong()) + p.toLong()
				var w_adj: Double = if (java.lang.Long.compareUnsigned(nd_idx, (nodes!!.dwf_qual_mass)!!.size()) < 0) (nodes!!.dwf_qual_mass)!!.a!![nd_idx.toInt()] else 0.0
				var w: Double = (if (c_dwf > 0.0) q * c_dwf else 0.0) + w_adj
				if (w == 0.0) {
					p++
					continue@__L2
				}
				if (java.lang.Long.compareUnsigned(nd_idx, (nodes!!.qual_mass_in)!!.size()) < 0) {
					(nodes!!.qual_mass_in)!!.a!![nd_idx.toInt()] += w
				}
				var pi: Long = p.toLong()
				if (java.lang.Long.compareUnsigned(pi, ((ctx!!.mass_balance)!!.qual_routing_dw_in)!!.size()) < 0) {
					((ctx!!.mass_balance)!!.qual_routing_dw_in)!!.a!![pi.toInt()] += w * dt
				}
				p++
			}
			i++
		}
	}

	open fun addGwLoads(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		if (!F_quality__anon_quality_QualityRouting_cpp.loadersNeeded_QualityRouting(np, ctx)) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var i: Int = 0
