				var c_link: Double = if (java.lang.Long.compareUnsigned(lp, (links!!.conc_old)!!.size()) < 0) (links!!.conc_old)!!.a!![lp.toInt()] else 0.0
				if (F_quality.linkTakesUpstreamValue(ctx, j)) {
					var source: Int = (if ((links!!.flow)!!.a!![uj.toInt()] >= 0.0) cpp.RefI.Arr((links!!.node1)!!.a, uj.toInt()) else cpp.RefI.Arr((links!!.node2)!!.a, uj.toInt()))!!.get()
					if (F_lidnode.active(ctx, source) || F_lidnode.active(ctx, downstream)) {
						c_link = ((ctx!!.nodes)!!.conc)!!.a!![((source * np) + p).toLong().toInt()]
						if (((ctx!!.nodes)!!.type)!!.a!![source.toLong().toInt()] == NodeType.OUTFALL) {
							c_link = if ((ctx!!.options)!!.outfall_backflow_zero) 0.0 else ((ctx!!.nodes)!!.conc_old)!!.a!![((source * np) + p).toLong().toInt()]
						}
					}
					c_link = F_lidnode.outletQuality(ctx, source, j, p, c_link)
				}
				var mass: Double = q * c_link
				if (F_quality.linkTakesUpstreamValue(ctx, j) && F_lidnode.active(ctx, downstream)) {
					var source_2: Int = (if ((links!!.flow)!!.a!![uj.toInt()] >= 0.0) cpp.RefI.Arr((links!!.node1)!!.a, uj.toInt()) else cpp.RefI.Arr((links!!.node2)!!.a, uj.toInt()))!!.get()
					if (((ctx!!.nodes)!!.type)!!.a!![source_2.toLong().toInt()] == NodeType.OUTFALL) {
