					}
				}
				if (java.lang.Long.compareUnsigned(np_idx, ((ctx!!.nodes)!!.qual_mass_in)!!.size()) < 0) {
					((ctx!!.nodes)!!.qual_mass_in)!!.a!![np_idx.toInt()] += mass
					F_lidnode.receiveQuality(ctx, downstream, j, q * dt, p, mass, dt)
				}
				p++
			}
			var r: Int = (ctx!!.node_subtypes)!!.storage_row(downstream)
			if (r >= 0) {
