	open fun mixAtNodes(ctx: SimulationContext?, dt: Double) {
		var np: Int = this.n_pollutants_
		var nodes: NodeData? = ctx!!.nodes
		var poll: PollutantData? = ctx!!.pollutants
		var mb: SimulationContext_MassBalance? = ctx!!.mass_balance
		var zero_bf_opt: Boolean = (ctx!!.options)!!.outfall_backflow_zero
		var reactions_active: Boolean = F_transport.legacyReactionsActive(ctx)
		var any_treatment: Boolean = (ctx!!.treatment)!!.hasAny()
		var i: Int = 0
		__L1@ while (i < ctx!!.n_nodes()) {
			var ui: Long = i.toLong()
			var v_old: Double = (nodes!!.old_volume)!!.a!![ui.toInt()]
			var v_in: Double = (nodes!!.qual_vol_in)!!.a!![ui.toInt()]
			var is_storage: Boolean = (nodes!!.type)!!.a!![ui.toInt()] == NodeType.STORAGE
			var zero_bf: Boolean = zero_bf_opt && ((nodes!!.type)!!.a!![ui.toInt()] == NodeType.OUTFALL)
			if (!F_quality.nodeIsReactor(ctx, i)) {
				var q_node: Double = if (dt > 0.0) v_in / dt else 0.0
				var p: Int = 0
				__L2@ while (p < np) {
					var idx: Long = (ui * np.toLong()) + p.toLong()
					if (java.lang.Long.compareUnsigned(idx, (nodes!!.conc)!!.size()) >= 0) {
						p++
						continue@__L2
					}
					if (q_node > F_quality.LEGACY_ZERO) {
						var mass_in: Double = if (java.lang.Long.compareUnsigned(idx, (nodes!!.qual_mass_in)!!.size()) < 0) (nodes!!.qual_mass_in)!!.a!![idx.toInt()] * dt else 0.0
						if (mass_in < 0.0) {
							var avail: Double = (nodes!!.conc_old)!!.a!![idx.toInt()] * v_old
							if (mass_in < (-avail)) {
								F_quality.bookNegativeSourceClamp(ctx, i, p, -(avail + mass_in))
								mass_in = -avail
							}
						}
						(nodes!!.conc)!!.a!![idx.toInt()] = mass_in / v_in
					} else {
						if (zero_bf) {
							(nodes!!.conc)!!.a!![idx.toInt()] = 0.0
						} else {
							if ((nodes!!.depth)!!.a!![ui.toInt()] > F_quality.ZERO_DEPTH) {
								(nodes!!.conc)!!.a!![idx.toInt()] = (nodes!!.conc_old)!!.a!![idx.toInt()]
							} else {
								(nodes!!.conc)!!.a!![idx.toInt()] = if (java.lang.Long.compareUnsigned(idx, (nodes!!.qual_mass_in)!!.size()) < 0) (nodes!!.qual_mass_in)!!.a!![idx.toInt()] else 0.0
							}
						}
					}
					p++
				}
				i++
				continue@__L1
			}
			var f_evap: Double = F_quality.storageEvapFactor(ctx, i)
			var q_exfil: Double = 0.0
			if (is_storage) {
				var srow: Int = (ctx!!.node_subtypes)!!.storage_row(i)
				if (srow >= 0) {
					var us: Long = srow.toLong()
					var st: StorageData? = (ctx!!.node_subtypes)!!.storages
					var v_exfil: Double = if (java.lang.Long.compareUnsigned(us, (st!!.exfil_loss)!!.size()) < 0) (st!!.exfil_loss)!!.a!![us.toInt()] else 0.0
					q_exfil = if (dt > 0.0) v_exfil / dt else 0.0
				}
			}
			var q_in: Double = if (dt > 0.0) v_in / dt else 0.0
			var dry: Boolean = F_quality.nodeIsDry(ctx, i, q_in) && (!F_lidnode.active(ctx, i))
			var p_2: Int = 0
			__L3@ while (p_2 < np) {
				var idx_2: Long = (ui * np.toLong()) + p_2.toLong()
				if (java.lang.Long.compareUnsigned(idx_2, (nodes!!.conc)!!.size()) >= 0) {
					p_2++
					continue@__L3
				}
				var up: Long = p_2.toLong()
				var c1: Double = (nodes!!.conc_old)!!.a!![idx_2.toInt()]
				var seeped: Double = (q_exfil * c1) * dt
				c1 *= f_evap
				var k: Double = if (java.lang.Long.compareUnsigned(up, (poll!!.k_decay)!!.size()) < 0) (poll!!.k_decay)!!.a!![up.toInt()] else 0.0
				if (reactions_active) {
					k = 0.0
				}
				if (((k != 0.0) && any_treatment) && F_quality__anon_quality_QualityRouting_cpp.nodeHasTreatmentFor_QualityRouting(ctx, i, p_2)) {
					k = 0.0
				}
				var reacted: Double = 0.0
				if (k != 0.0) {
					var c2: Double = cpp.M.max_d_d(0.0, c1 * (1.0 - (k * dt)))
					reacted = (c1 - c2) * v_old
					c1 = c2
				}
				var mass_in_2: Double = if (java.lang.Long.compareUnsigned(idx_2, (nodes!!.qual_mass_in)!!.size()) < 0) (nodes!!.qual_mass_in)!!.a!![idx_2.toInt()] * dt else 0.0
				if (mass_in_2 < 0.0) {
					var avail_2: Double = (nodes!!.conc_old)!!.a!![idx_2.toInt()] * v_old
					if (mass_in_2 < (-avail_2)) {
						F_quality.bookNegativeSourceClamp(ctx, i, p_2, -(avail_2 + mass_in_2))
						mass_in_2 = -avail_2
					}
				}
				var c_new: Double = 0.0
				if (q_in <= F_quality.LEGACY_ZERO) {
					c_new = c1
				} else {
					var c_in: Double = mass_in_2 / v_in
					var c_max: Double = cpp.M.max_d_d(c1, c_in)
					c_new = ((c1 * v_old) + mass_in_2) / (v_old + v_in)
					c_new = cpp.M.min_d_d(c_new, c_max)
					c_new = cpp.M.max_d_d(c_new, 0.0)
				}
				if (dry) {
					if (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_final_dry)!!.size()) < 0) {
						(mb!!.qual_routing_final_dry)!!.a!![up.toInt()] += c_new * (nodes!!.volume)!!.a!![ui.toInt()]
					}
					c_new = 0.0
				}
				c_new = cpp.M.max_d_d(c_new, 0.0)
				(nodes!!.conc)!!.a!![idx_2.toInt()] = c_new
				if ((reacted > 0.0) && (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_reacted)!!.size()) < 0)) {
					(mb!!.qual_routing_reacted)!!.a!![up.toInt()] += reacted
				}
				if ((seeped != 0.0) && (java.lang.Long.compareUnsigned(up, (mb!!.qual_routing_seep)!!.size()) < 0)) {
					(mb!!.qual_routing_seep)!!.a!![up.toInt()] += seeped
				}
				p_2++
			}
			i++
		}
	}

